import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import Sidebar from "../components/Sidebar";

function SocialScience() {
  const [sciences, setSciences] = useState([]);
  const [subsciences, setSubsciences] = useState([]);
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    async function fetchData() {
      try {
        const res = await fetch("http://localhost:8080/resources");
        const data = await res.json();
        setSciences(data.sciences || []);
        setSubsciences(data.subsciences || []);
      } catch (err) {
        console.error("SocialScience fetch error:", err);
      } finally {
        setLoading(false);
      }
    }

    fetchData();
  }, []);

  function getSubsciencesForScience(scienceId) {
    return subsciences.filter((s) => s.science_id === scienceId);
  }

  const science = sciences.find((s) => s.code && s.code.toLowerCase() === "social");

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Social Science</h1>
            <p className="dashboard-subtitle">Explore Human Geography, Psychology, Economics and History.</p>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading...</p>
        ) : (
          <div className="resources-layout">
            <section className={`resources-section resources-social`}>
              <div className="resources-section-header">
                <h2>Social Science</h2>
                <p>Understand people, societies and the forces that shape them.</p>
              </div>

              <div className="resources-subscience-grid">
                {science ? (
                  getSubsciencesForScience(science.id).map((sub) => (
                    <div
                      key={sub.id}
                      className="resources-subscience-card"
                      onClick={() => navigate(`/subscience/${sub.id}`)}
                    >
                      <h3>{sub.name}</h3>
                      <p className="resources-subscience-code">{science.code.toUpperCase()} • {sub.code.toUpperCase()}</p>
                      <p className="resources-subscience-desc">10-lesson unit • XP, games, tutors, and Q&A.</p>
                    </div>
                  ))
                ) : (
                  <p className="muted">No social science data found.</p>
                )}
              </div>
            </section>
          </div>
        )}
      </main>
    </div>
  );
}

export default SocialScience;
